export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const held = getDb()
    .select({ org: organizations })
    .from(organizationSlugHolds)
    .innerJoin(organizations, eq(organizations.id, organizationSlugHolds.orgId))
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return held ? toOrganization(held.org) : null;
}

/**
 * Whether `orgId` may take `slug` as its current slug: no other workspace
 * (deleted or not) holds it as current, and no other workspace holds it
 * retired. Its own retired slugs are always available to it.
 */
export async function isSlugAvailableForOrg(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const db = getDb();
  const current = db
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (current && current.id !== orgId) return false;

  const held = db
    .select({ orgId: organizationSlugHolds.orgId })
    .from(organizationSlugHolds)
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
      ),
    )
    .all();
  return held.every((hold) => hold.orgId === orgId);
}

/**
 * Swaps the current slug and retires the old one in a single transaction.
 * Renaming back to a slug this org retired ends that retirement.
 */
export async function changeOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const now = toIsoTimestamp(new Date());
    tx.delete(organizationSlugHolds)
      .where(
        and(
          eq(organizationSlugHolds.orgId, orgId),
          eq(organizationSlugHolds.slug, to),
        ),
      )
      .run();
    // Stale (expired) holds on the slug being retired are superseded.
    tx.delete(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, from))
      .run();
    tx.insert(organizationSlugHolds)
      .values({ slug: from, orgId, retiredAt: now })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug: to, updatedAt: now })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();
    if (!row) throw new Error(`Organization ${orgId} not found`);
    return toOrganization(row);
  });
